using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class AdultMarriageTests
{
    static readonly EntityId Player=new("created:test"),Other=new("created:other"),Third=new("created:third");
    static RegisteredOfficer Officer(string id,bool declared=true)=>NewGameWorldTests.Officer(id) with{InitialMaritalStatus=declared?InitialMaritalStatus.Unmarried:null};
    static WorldSession Start(ulong seed=42,bool on=true,bool declared=true,bool lord=false,bool minor=false,bool absent=false){var a=Officer(Player.Value) with{Role=lord?StartTemplate.Daimyo:StartTemplate.Ronin,FactionName=lord?"鏡山家":null};var b=Officer(Other.Value,declared) with{BirthYear=minor?1550:1520,Site=absent?"site:kofu":"site:castle"};var setup=NewGameWorldTests.Setup([a,b,Officer(Third.Value)],lord?[new(a.Id,"org:created-test",[a.Site],false)]:[]);return new(NewGameWorld.Create(setup.World,setup.Registered,a.Id,seed,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,companionPolicy:PersonalCompanions.Policy,developmentPolicy:CharacterDevelopment.Policy,socialPolicy:CharacterRelations.Policy,adoptionPolicy:AdultAdoption.Policy,marriagePolicy:on?AdultMarriage.Policy:null));}
    static readonly Lazy<ulong> Yes=new(()=>Find(true)),No=new(()=>Find(false));
    static ulong Find(bool answer){for(ulong n=1;n<100;n++){var w=Start(n).DiagnosticSnapshot();if((CharacterRelations.DiagnosticTrait(w,Other,SocialTrait.Duty)+CharacterRelations.DiagnosticTrait(w,Other,SocialTrait.Affection)>=80)==answer)return n;}throw new Exception("Missing branch seed");}
    static void At(WorldSession s,long at)=>NewGameWorldTests.At(s,at);
    static CommandResult Act(WorldSession s,MarriageAction action,EntityId? root=null,EntityId? house=null,string? id=null,EntityId? other=null)=>s.DecideMarriage(new(new(id??"request:marriage/"+s.Revision),action,action==MarriageAction.Propose?other??Other:null,root,house),s.PlayerControl,s.Revision);
    static EntityId Propose(WorldSession s){Assert.Equal(ResultCode.Accepted,Act(s,MarriageAction.Propose).Code);return s.DiagnosticSnapshot().Marriage!.Entries.Last().Input.Id;}
    static WorldSession Agreed(bool lord=false){var s=Start(Yes.Value,lord:lord);Propose(s);At(s,1);Assert.Single(s.DiagnosticSnapshot().Marriage!.Entries,e=>e.Input.Action==MarriageAction.PersonalYes);return s;}
    static void Implement(WorldSession s){var t=s.DiagnosticSnapshot().Marriage!.Entries.First().Terms!;foreach(var h in t.Houses)Assert.Equal(ResultCode.Accepted,Act(s,MarriageAction.ApproveHouse,t.Id,h.Owner).Code);Assert.Equal(ResultCode.Accepted,Act(s,MarriageAction.Implement,t.Id).Code);}
    [Fact]public void UnknownAuthoringStatusIsNotAssumedUnmarried(){var s=Start(declared:false);Assert.DoesNotContain(Other,AdultMarriage.Candidates(s.DiagnosticSnapshot()));Assert.Equal(ResultCode.NotAvailable,Act(s,MarriageAction.Propose).Code);}
    [Fact]public void HistoricalSpouseDataIsNotInvented(){var s=Start();Assert.DoesNotContain(new EntityId("person:nobunaga"),AdultMarriage.Candidates(s.DiagnosticSnapshot()));Assert.Equal(ResultCode.NotAvailable,Act(s,MarriageAction.Propose,other:new("person:nobunaga")).Code);}
    [Fact]public void OldPolicyDoesNotGainMarriage(){var s=Start(on:false);Assert.Null(s.DiagnosticSnapshot().Marriage);Assert.DoesNotContain("MarriagePolicy",System.Text.Encoding.UTF8.GetString(ContractJson.Write(s.DiagnosticSnapshot())));Assert.Equal(ResultCode.NotAvailable,Act(s,MarriageAction.Propose).Code);}
    [Fact]public void OldRegisteredDataRoundTripsWithoutDeclaration(){var p=NewGameWorldTests.Officer();var bytes=ContractJson.Write(p);Assert.DoesNotContain("InitialMaritalStatus",System.Text.Encoding.UTF8.GetString(bytes));Assert.Equal(bytes,ContractJson.Write(ContractJson.Read<RegisteredOfficer>(bytes)));}
    [Fact]public void DeclarationSurvivesLibraryImportIndependentCopyAndDisk(){var p=Officer(Player.Value);var lib=OfficerLibraryStore.Import(new(1,[],[new("group:test","別設定",[])]),new(1,[p],[]));lib=NewGameSetup.CopyToGroup(lib,p.Id,"group:test","created:copy");var store=new OfficerLibraryStore(Path.Combine(Path.GetTempPath(),"marriage-library-"+Guid.NewGuid().ToString("N")));store.Save(lib,null);var loaded=store.Load();Assert.Equal(InitialMaritalStatus.Unmarried,loaded.Groups[0].Officers[0].InitialMaritalStatus);Assert.Equal(ContractJson.Write(lib),ContractJson.Write(loaded));loaded=loaded with{Ungrouped=[p with{InitialMaritalStatus=null}]};Assert.Equal(InitialMaritalStatus.Unmarried,loaded.Groups[0].Officers[0].InitialMaritalStatus);}
    [Fact]public void InvalidDeclarationIsRejected(){var p=Officer(Player.Value) with{InitialMaritalStatus=(InitialMaritalStatus)99};Assert.Throws<InvalidDataException>(()=>NewGameSetup.Validate(new OfficerLibrary(1,[p],[])));}
    [Fact]public void NewCampaignProfileRebuildPreservesDeclaredStatus(){var setup=NewGameWorldTests.Setup([Officer(Player.Value),Officer(Other.Value)]);var store=new NewCampaignStore(Path.Combine(Path.GetTempPath(),"marriage-profile-"+Guid.NewGuid().ToString("N")));var p=store.New(setup.World,setup.Registered,Player.Value,42,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,companionPolicy:PersonalCompanions.Policy,socialPolicy:CharacterRelations.Policy,adoptionPolicy:AdultAdoption.Policy,marriagePolicy:AdultMarriage.Policy);var w=NewCampaignStore.Build(p);Assert.Equal(AdultMarriage.Policy,w.NewGame!.MarriagePolicy);Assert.All(w.NewGame.Registered,x=>Assert.Equal(InitialMaritalStatus.Unmarried,x.InitialMaritalStatus));}
    [Fact]public void PersonalConsentDoesNotAutoImplementOrChangeRights(){var s=Agreed();var before=s.DiagnosticSnapshot();Assert.DoesNotContain(before.Marriage!.Entries,e=>e.Input.Action==MarriageAction.Implement);Implement(s);var w=s.DiagnosticSnapshot();Assert.Single(w.Marriage!.Entries,e=>e.Input.Action==MarriageAction.Implement);Assert.Equal(ContractJson.Write(before.Memberships),ContractJson.Write(w.Memberships));Assert.Equal(ContractJson.Write(before.Offices),ContractJson.Write(w.Offices));Assert.Equal(ContractJson.Write(before.LandRights),ContractJson.Write(w.LandRights));Assert.Equal(ContractJson.Write(before.Treaties),ContractJson.Write(w.Treaties));Assert.Equal(NewGameWork.Balance(before,Player),NewGameWork.Balance(w,Player));}
    [Fact]public void PlayerHouseConsentRemainsSeparate(){var s=Agreed(true);var t=s.DiagnosticSnapshot().Marriage!.Entries.First().Terms!;Assert.Single(t.Houses);Assert.Equal(ResultCode.NotAvailable,Act(s,MarriageAction.Implement,t.Id).Code);Implement(s);}
    [Fact]public void RefusalCannotBeOverriddenByImplementation(){var s=Start(No.Value);var root=Propose(s);At(s,1);Assert.Single(s.DiagnosticSnapshot().Marriage!.Entries,e=>e.Input.Action==MarriageAction.PersonalNo);Assert.Equal(ResultCode.NotAvailable,Act(s,MarriageAction.Implement,root).Code);}
    [Fact]public void WithdrawalPreventsLaterAnswer(){var s=Start(Yes.Value);var root=Propose(s);Assert.Equal(ResultCode.Accepted,Act(s,MarriageAction.Withdraw,root).Code);At(s,5);Assert.Equal(2,s.DiagnosticSnapshot().Marriage!.Entries.Length);}
    [Fact]public void ExpiredConsentCannotImplement(){var s=Agreed();At(s,604801);Assert.Equal(ResultCode.NotAvailable,Act(s,MarriageAction.Implement,s.DiagnosticSnapshot().Marriage!.Entries.First().Input.Id).Code);}
    [Theory][InlineData(true,false)][InlineData(false,true)]public void MinorOrAbsentCannotEnterMarriage(bool minor,bool absent){var s=Start(minor:minor,absent:absent);Assert.Equal(ResultCode.NotAvailable,Act(s,MarriageAction.Propose).Code);Assert.DoesNotContain(Other,AdultMarriage.Candidates(s.DiagnosticSnapshot()));}
    [Fact]public void PendingOrCompletedMarriageBlocksThirdParty(){var s=Agreed();Assert.Equal(ResultCode.NotAvailable,Act(s,MarriageAction.Propose,other:Third).Code);Implement(s);Assert.Equal(ResultCode.NotAvailable,Act(s,MarriageAction.Propose,other:Third).Code);Assert.Empty(AdultMarriage.Candidates(s.DiagnosticSnapshot()));}
    [Fact]public void RetryIsIdempotentAndNpcResponseCannotBeForged(){var s=Start(Yes.Value);var root=Propose(s);Assert.Equal(ResultCode.AlreadyAccepted,Act(s,MarriageAction.Propose,id:root.Value).Code);Assert.Equal(ResultCode.IdPayloadConflict,Act(s,MarriageAction.Propose,id:root.Value,other:Third).Code);Assert.Equal(ResultCode.NotAvailable,Act(s,MarriageAction.PersonalYes,root).Code);}
    static EntityId Adopt(WorldSession s,EntityId other,bool implement=true){var id=new EntityId("request:marriage-adopt/"+s.Revision);Assert.Equal(ResultCode.Accepted,s.DecideAdoption(new(id,AdoptionAction.Propose,other),s.PlayerControl,s.Revision).Code);At(s,s.Seconds+1);if(implement)Assert.Equal(ResultCode.Accepted,s.DecideAdoption(new(new("request:adoption-apply/"+s.Revision),AdoptionAction.Implement,Original:id),s.PlayerControl,s.Revision).Code);return id;}
    [Fact]public void AdoptiveParentChildCannotMarry(){var s=Start(Yes.Value);Adopt(s,Other);Assert.Equal(ResultCode.NotAvailable,Act(s,MarriageAction.Propose).Code);}
    [Fact]public void MarriageFirstBlocksLaterParentChildAdoption(){var s=Agreed();Implement(s);Assert.Equal(ResultCode.NotAvailable,s.DecideAdoption(new(new("request:spouse-adopt"),AdoptionAction.Propose,Other),s.PlayerControl,s.Revision).Code);}
    [Fact]public void PendingMarriageBlocksAdoptionImplementationWithoutRewritingOriginal(){var s=Start(Yes.Value);var original=Adopt(s,Other,false);var marriage=Propose(s);Assert.Equal(ResultCode.NotAvailable,s.DecideAdoption(new(new("request:blocked-adopt"),AdoptionAction.Implement,Original:original),s.PlayerControl,s.Revision).Code);Assert.Equal(ResultCode.Accepted,Act(s,MarriageAction.Withdraw,marriage).Code);Assert.Equal(ResultCode.Accepted,s.DecideAdoption(new(new("request:resumed-adopt"),AdoptionAction.Implement,Original:original),s.PlayerControl,s.Revision).Code);new WorldSession(s.DiagnosticSnapshot());}
    [Fact]public void DepartingAfterConsentMakesImplementationUnavailable(){var s=Agreed();var root=s.DiagnosticSnapshot().Marriage!.Entries.First().Input.Id;Assert.Equal(ResultCode.Accepted,s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:marriage-leave","fork"),s.Revision).Code);Assert.Equal(ResultCode.NotAvailable,Act(s,MarriageAction.Implement,root).Code);At(s,10);new WorldSession(s.DiagnosticSnapshot());}
    [Fact]public void MarriageIdsCannotBecomeOrdinaryRequests(){var s=Start(Yes.Value);var root=Propose(s);Assert.Equal(ResultCode.IdPayloadConflict,s.Submit(NewGameWorld.Inspect(s.DiagnosticSnapshot(),root.Value),s.Revision).Code);}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)][InlineData(4)][InlineData(5)]public void ActualGenerationRecoveryPreservesMarriageAndFuture(int phase){var s=Start(phase==4?No.Value:Yes.Value,lord:phase is 2 or 3);var root=Propose(s);if(phase>0)At(s,1);if(phase==3)Implement(s);if(phase==5)Assert.Equal(ResultCode.Accepted,Act(s,MarriageAction.Withdraw,root).Code);s.SetPaused(true);var w=s.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"marriage-"+Guid.NewGuid().ToString("N")),w.Definitions);Assert.True(store.Save(s,"marriage",w.WorldId).Published);var host=new WorldSessionHost(Start());Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("marriage"),host.Current,host.Current.Revision));Assert.Equal(ContractJson.Write(w),ContractJson.Write(host.Current.DiagnosticSnapshot()));Assert.Equal(ContractJson.Write(AdultMarriage.View(w)),ContractJson.Write(AdultMarriage.View(host.Current.DiagnosticSnapshot())));var dir=Environment.GetEnvironmentVariable("HAKUTAI_WORLD_CLASH_QA_DIR");if(!string.IsNullOrEmpty(dir)){Directory.CreateDirectory(dir);File.WriteAllBytes(Path.Combine(dir,"adult-marriage-"+phase+".before.json"),ContractJson.Write(w));File.WriteAllBytes(Path.Combine(dir,"adult-marriage-"+phase+".restored.json"),ContractJson.Write(host.Current.DiagnosticSnapshot()));}foreach(var x in new[]{s,host.Current})At(x,x.Seconds+10);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(host.Current.DiagnosticSnapshot()));}

    [Fact]public void ActualTwoAdoptionsShareAnAncestorWithoutInventingBloodKin(){ulong seed=0;for(ulong n=1;n<100;n++){var w=Start(n).DiagnosticSnapshot();if(new[]{Other,Third}.All(id=>CharacterRelations.DiagnosticTrait(w,id,SocialTrait.Duty)+CharacterRelations.DiagnosticTrait(w,id,SocialTrait.Affection)>=80)){seed=n;break;}}Assert.True(seed>0);var s=Start(seed);Adopt(s,Other);Adopt(s,Third);var type=typeof(AdultMarriage).Assembly.GetType("HakutaiKagami.Core.Contracts.FamilyConsentRules")!;var method=type.GetMethod("Related",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic)!;Assert.True((bool)method.Invoke(null,new object?[]{s.DiagnosticSnapshot(),Other,Third,s.Seconds,s.Revision+1,null})!);Assert.False((bool)method.Invoke(null,new object?[]{s.DiagnosticSnapshot(),Other,new EntityId("person:nobunaga"),s.Seconds,s.Revision+1,null})!);}
}
